import{_ as a,c as e,o,b0 as d}from"./chunks/framework.C5ev1SXp.js";const r="/scm-docs/assets/journey-flowchart.D10CkXuS.svg",c="/scm-docs/assets/two-sessions-sequence.DxwuzxO2.svg",s="/scm-docs/assets/protocol-stack.C_X3kBso.svg",q=JSON.parse('{"title":"LV055-浏览器输入到页面显示的全过程","description":null,"frontmatter":{"title":"LV055-浏览器输入到页面显示的全过程","date":"2026-10-15T07:05:27.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d629b273f0ccc3ba1e2c8","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-15T07:05:27.204Z","fulluuid":"c3ba1e2c88d14726a43b5b9f4d6a34d3","useduuid":"c3ba1e2c8"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d629b273f0ccc3ba1e2c8.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV055-浏览器输入到页面显示的全过程.md","lastUpdated":1792231946000}'),i={name:"sdoc/advanced-chapter/network-basics/126d629b273f0ccc3ba1e2c8.md"};function h(l,t,n,p,u,b){return o(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="lv055-浏览器输入到页面显示的全过程" tabindex="-1">LV055-浏览器输入到页面显示的全过程 <a class="header-anchor" href="#lv055-浏览器输入到页面显示的全过程" aria-label="Permalink to &quot;LV055-浏览器输入到页面显示的全过程&quot;">​</a></h1><h2 id="一、-拆解输入-这不是一个网址" tabindex="-1">一、 拆解输入：这不是一个网址 <a class="header-anchor" href="#一、-拆解输入-这不是一个网址" aria-label="Permalink to &quot;一、 拆解输入：这不是一个网址&quot;">​</a></h2><p>在浏览器地址栏敲下&quot;github是什么&quot;再按下 Enter——很多人以为这会直接连上 GitHub，其实第一件事就错了：<strong>这不是 URL，是一串搜索关键词</strong>。</p><h3 id="_1-地址栏的两个身份" tabindex="-1">1. 地址栏的两个身份 <a class="header-anchor" href="#_1-地址栏的两个身份" aria-label="Permalink to &quot;1. 地址栏的两个身份&quot;">​</a></h3><p>现代浏览器的地址栏（Chrome 里叫 omnibox）承担两种职责：输入合法网址就当 URL 直接访问；输入的不是网址，就转交给<strong>默认搜索引擎</strong>。浏览器判断的依据大致是：</p><p>（1）字符串里有协议头（<code>https://</code>）、有合法域名（含 <code>.</code> 且各段合法）、或以 <code>localhost</code> / IP 地址开头 → 当作 URL 处理。</p><p>（2）含空格、纯中文、或者&quot;点号分段&quot;不满足域名字符规则 → 当作搜索词。</p><p>&quot;github是什么&quot;含中文、没有点号，显然落在第二类。浏览器会把它拼进搜索引擎的搜索模板，比如百度是 <code>https://www.baidu.com/s?wd=&lt;关键词&gt;</code>。</p><h3 id="_2-搜索引擎拿到了什么" tabindex="-1">2. 搜索引擎拿到了什么 <a class="header-anchor" href="#_2-搜索引擎拿到了什么" aria-label="Permalink to &quot;2. 搜索引擎拿到了什么&quot;">​</a></h3><p>关键词不会原样出现在 URL 里。浏览器先对它做 <strong>URL 编码</strong>（百分号编码）：&quot;github是什么&quot; 变成 <code>github%E6%98%AF%E4%BB%80%E4%B9%88</code>——&quot;是&quot;和&quot;什&quot;、&quot;么&quot;三个汉字按 UTF-8 各占 3 字节，每字节写成 <code>%XX</code>。所以浏览器真正发起的第一个请求是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.baidu.com/s?wd=github%E6%98%AF%E4%BB%80%E4%B9%88</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>从按下 Enter 到这一步只过了几毫秒，网络之旅尚未开始，但输入已经被&quot;翻译&quot;成了网络能理解的形式。整趟旅程先看总览：</p><p><img src="'+r+'" alt="从输入到画面的完整旅程"></p><h2 id="二、-第一步-把关键词交给搜索引擎" tabindex="-1">二、 第一步：把关键词交给搜索引擎 <a class="header-anchor" href="#二、-第一步-把关键词交给搜索引擎" aria-label="Permalink to &quot;二、 第一步：把关键词交给搜索引擎&quot;">​</a></h2><h3 id="_1-dns-查出搜索服务器的-ip" tabindex="-1">1. DNS：查出搜索服务器的 IP <a class="header-anchor" href="#_1-dns-查出搜索服务器的-ip" aria-label="Permalink to &quot;1. DNS：查出搜索服务器的 IP&quot;">​</a></h3><p>URL 里的 <code>www.baidu.com</code> 只是给人看的名字，发包前必须先换成 IP 地址。浏览器按这个顺序查 DNS 缓存：</p><p>（1）浏览器自身缓存；</p><p>（2）操作系统缓存与 <code>hosts</code> 文件；</p><p>（3）本机配置的 DNS 服务器（家用网络里通常就是路由器），查不到会递归问根域名服务器、<code>.com</code> 顶级域服务器、<code>baidu.com</code> 权威服务器，最终拿到 IP。</p><p>这一步用的是 UDP 53 端口。顺带一提，家庭网络的 IP、子网掩码、DNS 服务器地址多半是开机时 DHCP 自动发下来的，参见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0326cce94ffc3.html">LV040-DHCP与IP地址自动获取</a>。</p><h3 id="_2-tcp-与-tls-建立加密通道" tabindex="-1">2. TCP 与 TLS：建立加密通道 <a class="header-anchor" href="#_2-tcp-与-tls-建立加密通道" aria-label="Permalink to &quot;2. TCP 与 TLS：建立加密通道&quot;">​</a></h3><p>拿到 IP 后，浏览器发起 HTTPS 请求，先走 TCP：</p><p>（1）与服务器 IP 的 443 端口完成<strong>三次握手</strong>，建立 TCP 连接（握手细节见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.html">LV035-传输层端口UDP与TCP</a>）。</p><p>（2）在这条 TCP 连接上做 <strong>TLS 握手</strong>：协商加密套件、验证服务器证书、交换密钥，之后的应用数据全部加密传输。这是 URL 能写 <code>https</code> 的原因。</p><p>（3）发送 <code>GET /s?wd=github%E6%98%AF... HTTP/1.1</code>，带上 <code>Host</code>、浏览器标识等请求头。</p><p>（4）服务器返回 <code>200 OK</code> 和一整页 HTML——搜索结果页的正文就是这串 UTF-8 字节。</p><p>如果本机还没学到网关的 MAC 地址，发包前还有一次 ARP 请求打头阵（见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030-ARP与MAC地址</a>）；包出内网、跨路由的路径选择见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.html">LV015-网关与跨网段通信</a>。</p><h3 id="_3-结果页在本地成形" tabindex="-1">3. 结果页在本地成形 <a class="header-anchor" href="#_3-结果页在本地成形" aria-label="Permalink to &quot;3. 结果页在本地成形&quot;">​</a></h3><p>浏览器收到 HTML 后立刻进入渲染流水线（渲染细节统一放在第四章讲），几百毫秒后，你看到了一列搜索结果——其中通常第一条是 GitHub 官网或它的某个中文介绍页。<strong>到这里为止，我们还没有碰过 GitHub 一次</strong>：搜索是搜索引擎替你完成的，它爬的是早已抓好的网页库。</p><h2 id="三、-第二步-点击结果-向-github-发起请求" tabindex="-1">三、 第二步：点击结果，向 GitHub 发起请求 <a class="header-anchor" href="#三、-第二步-点击结果-向-github-发起请求" aria-label="Permalink to &quot;三、 第二步：点击结果，向 GitHub 发起请求&quot;">​</a></h2><h3 id="_1-又一次-dns-这次查-github-com" tabindex="-1">1. 又一次 DNS，这次查 github.com <a class="header-anchor" href="#_1-又一次-dns-这次查-github-com" aria-label="Permalink to &quot;1. 又一次 DNS，这次查 github.com&quot;">​</a></h3><p>点击结果链接，浏览器对 <code>github.com</code> 走一遍同样的 DNS 流程。GitHub 的域名解析通常返回多个 A 记录 / AAAA 记录，配合 CDN，会把用户引导到离自己最近的接入点——这是大厂网站的常规做法。</p><h3 id="_2-握手、请求、响应" tabindex="-1">2. 握手、请求、响应 <a class="header-anchor" href="#_2-握手、请求、响应" aria-label="Permalink to &quot;2. 握手、请求、响应&quot;">​</a></h3><p>接下来与搜索那一步完全同构：</p><p>（1）TCP 三次握手连上 GitHub 的 443 端口；</p><p>（2）TLS 握手验证 <code>github.com</code> 的证书（证书里的域名必须与你访问的一致，否则浏览器报安全警告）；</p><p>（3）发出 <code>GET / HTTP/1.1</code>；</p><p>（4）服务器返回首页 HTML，状态码 200。</p><p>一个细节：国内网络环境下，这一步可能失败或超时——表现就是浏览器转圈后报&quot;无法访问此网站&quot;。<strong>DNS 正常、握手不通</strong>，恰恰说明问题出在 IP 可达性而不是域名解析，这是排查网络问题时的基本判断方法（工具用法见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0347a8c2e0d9b.html">LV045-网络调试工具与抓包</a>）。</p><p>两段请求的完整时序（消息谁先谁后、谁是请求谁是响应）画在一张图里：</p><p><img src="'+c+'" alt="搜索与访问GitHub的时序"></p><h3 id="_3-首页-html-只是个开头" tabindex="-1">3. 首页 HTML 只是个开头 <a class="header-anchor" href="#_3-首页-html-只是个开头" aria-label="Permalink to &quot;3. 首页 HTML 只是个开头&quot;">​</a></h3><p>GitHub 首页的 HTML 文档本身不大，但里面引用了数十个静态资源：JavaScript 脚本、样式表、字体、图标、头像图片等，分别挂在 <code>github.githubassets.com</code>、<code>avatars.githubusercontent.com</code> 这些 CDN 域名下。浏览器要再为每个域名做 DNS + 握手 + 请求，这解释了为什么&quot;页面开始显示&quot;和&quot;页面加载完&quot;是两件事。</p><h2 id="四、-第三步-浏览器把字节变成画面" tabindex="-1">四、 第三步：浏览器把字节变成画面 <a class="header-anchor" href="#四、-第三步-浏览器把字节变成画面" aria-label="Permalink to &quot;四、 第三步：浏览器把字节变成画面&quot;">​</a></h2><p>网络部分到此结束，剩下的发生在浏览器进程内部——渲染引擎把 HTTP 响应的字节流变成屏幕上的像素。</p><h3 id="_1-解析-从-html-到-dom" tabindex="-1">1. 解析：从 HTML 到 DOM <a class="header-anchor" href="#_1-解析-从-html-到-dom" aria-label="Permalink to &quot;1. 解析：从 HTML 到 DOM&quot;">​</a></h3><p>渲染引擎逐字节读入 HTML，按语法规则解析成一棵 <strong>DOM 树</strong>（文档对象模型）。解析过程中遇到 <code>&lt;link rel=&quot;stylesheet&quot;&gt;</code>、<code>&lt;script src&gt;</code>、<code>&lt;img&gt;</code> 等标签，就向对应 URL 发起资源请求——这就是上一节说的&quot;后续资源&quot;。这些请求与主文档的请求并发行进，受浏览器的同域名并发连接数限制。</p><h3 id="_2-样式与绘制" tabindex="-1">2. 样式与绘制 <a class="header-anchor" href="#_2-样式与绘制" aria-label="Permalink to &quot;2. 样式与绘制&quot;">​</a></h3><p>CSS 被解析成 <strong>CSSOM</strong>，与 DOM 合成<strong>渲染树</strong>；随后浏览器计算每个节点的几何位置（布局 / reflow），再逐层绘制到屏幕上（绘制 / paint）。传统流水线是&quot;布局 → 绘制 → 合成&quot;，现代浏览器把页面切成若干图层分别绘制，最后由合成线程合帧，滚动动画因此可以不经过主线程。</p><h3 id="_3-javascript-的位置" tabindex="-1">3. JavaScript 的位置 <a class="header-anchor" href="#_3-javascript-的位置" aria-label="Permalink to &quot;3. JavaScript 的位置&quot;">​</a></h3><p><code>&lt;script&gt;</code> 默认会阻塞 HTML 解析——脚本可能修改 DOM，必须先执行完再继续。GitHub 这类现代站点大量依赖 JS：首屏骨架先渲染出来，动态数据（时间线、通知数等）由脚本再发 AJAX / fetch 请求补上。所以你在屏幕上看到&quot;最终页面&quot;之前，背后可能又发生了几十次小请求，只是用户感知不到。</p><p>整条渲染流水线跑完，从敲下 Enter 算起通常在数百毫秒到几秒之间，其中网络传输占了绝大部分时间。</p><h2 id="五、-全程协议清单" tabindex="-1">五、 全程协议清单 <a class="header-anchor" href="#五、-全程协议清单" aria-label="Permalink to &quot;五、 全程协议清单&quot;">​</a></h2><p>把这次旅程浓缩成一张表，每个环节都能在本目录找到对应的展开篇：</p><table tabindex="0"><thead><tr><th>环节</th><th>动作</th><th>用到的协议 / 机制</th><th>本目录对应篇</th></tr></thead><tbody><tr><td>判定输入</td><td>关键词 → 搜索 URL</td><td>URL 编码</td><td>——</td></tr><tr><td>找服务器</td><td>域名 → IP</td><td>DNS（UDP 53）</td><td><a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0326cce94ffc3.html">LV040-DHCP</a>（DNS 地址从哪来）</td></tr><tr><td>出内网</td><td>IP → MAC</td><td>ARP</td><td><a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030-ARP与MAC地址</a></td></tr><tr><td>跨网段</td><td>逐跳转发</td><td>IP + 路由</td><td><a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.html">LV015-网关与跨网段通信</a></td></tr><tr><td>建连接</td><td>三次握手</td><td>TCP</td><td><a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.html">LV035-传输层端口UDP与TCP</a></td></tr><tr><td>加密</td><td>TLS 握手</td><td>TLS</td><td>——</td></tr><tr><td>取数据</td><td>请求与响应</td><td>HTTP / HTTPS</td><td>——</td></tr><tr><td>成画面</td><td>渲染</td><td>DOM / CSSOM / JS</td><td>——</td></tr></tbody></table><p>未列出的部分（TLS、HTTP 细节、渲染引擎）属于应用层与浏览器专题，超出&quot;网络基础&quot;的边界，这里只给出它们在整个链条中的位置。</p><p>这些协议自上而下各占协议栈一层，一层只对上一层负责：</p><p><img src="'+s+'" alt="一次HTTPS访问经过的协议栈分层"></p><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>&quot;github是什么&quot;不是 URL，浏览器把它交给默认搜索引擎，先做 URL 编码再发起请求。</li><li>完整链路是：DNS 查 IP → ARP 找网关 → 路由转发 → TCP 握手 → TLS 握手 → HTTP 请求响应，搜索与点击结果各走一遍。</li><li>看到页面 ≠ 加载完：HTML 先到先渲染，样式、脚本、图片等资源还在并发请求。</li><li>渲染引擎把字节变成 DOM、CSSOM、渲染树，最后绘制合帧；JS 会阻塞解析，动态内容靠二次请求补齐。</li><li>这趟旅程串起了本目录的分层模型、IP、ARP、路由、TCP、DHCP 各篇——网络基础课的终点，就是能对任何一次&quot;上网&quot;说出每一跳发生了什么。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>整体流程的经典综述：<a href="https://github.com/alex/what-happens-when" target="_blank" rel="noreferrer">What really happens when you navigate to a URL</a>（GitHub 上的开源协作文档）</li><li>渲染流水线：<a href="https://developer.mozilla.org/zh-CN/docs/Web/Performance/How_browsers_work" target="_blank" rel="noreferrer">MDN — Populating the page: how browsers work</a></li><li>URL 编码标准：<a href="https://datatracker.ietf.org/doc/html/rfc3986" target="_blank" rel="noreferrer">RFC 3986 — Uniform Resource Identifier</a></li><li>姊妹篇：<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.html">LV050-一次ping的完整旅程</a>（同一套链路的命令行视角）</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',65)])])}const P=a(i,[["render",h]]);export{q as __pageData,P as default};
